import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Authoring Rule Sources","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/rule-source.md","filePath":"en/guide/rule-source.md","lastUpdated":1785861127000}'),n={name:"en/guide/rule-source.md"};function o(r,e,l,d,h,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="authoring-rule-sources" tabindex="-1">Authoring Rule Sources <a class="header-anchor" href="#authoring-rule-sources" aria-label="Permalink to &quot;Authoring Rule Sources&quot;">​</a></h1><p>A rule source lets anyone maintain and distribute their own cleaning rules. It is just a JSON file served over HTTP: users paste the link into CZeroX to subscribe, and it <strong>updates automatically once a day</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Who this is for</p><p>This page is for developers publishing rules to CZero users. <strong>Hosting from your own repo is recommended</strong>; the CZero repo keeps a fallback slot as well.</p><p>If you only want a few paths for your own device, add them directly under <strong>Custom rules → Built-in rules</strong> in CZeroX — you don&#39;t need a rule source.</p><p>The Chinese page is the canonical one and may be more current: <a href="/guide/rule-source">开发规则源</a>.</p></div><h2 id="file-format" tabindex="-1">File format <a class="header-anchor" href="#file-format" aria-label="Permalink to &quot;File format&quot;">​</a></h2><p>A rule source has the same shape as the module&#39;s local <code>clean_paths.json</code>, with attribution fields added at the top level:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Wang&#39;s rule source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;author&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@laowang&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026.08.04&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;homepage&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/laowang/czero-rules&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;groups&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Weibo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;paths&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;/storage/emulated/0/Android/data/com.sina.weibo/cache&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;/data/data/com.sina.weibo/files/weibo_log&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Xiaohongshu&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;paths&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;/storage/emulated/0/Android/data/com.xingin.xhs/cache/*&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Export the rules you curated in CZeroX, add <code>name</code> and <code>author</code>, and you have a working source.</p><h2 id="top-level-fields" tabindex="-1">Top-level fields <a class="header-anchor" href="#top-level-fields" aria-label="Permalink to &quot;Top-level fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td><strong>yes</strong></td><td>Source name, shown as the card title. Truncated past 64 chars</td></tr><tr><td><code>author</code></td><td>string</td><td>no</td><td>Attribution, shown under the title. Max 64 chars</td></tr><tr><td><code>version</code></td><td>string</td><td>no</td><td>Version marker, any format; a date reads best. Max 32 chars</td></tr><tr><td><code>homepage</code></td><td>string</td><td>no</td><td>Project page. Max 256 chars</td></tr><tr><td><code>groups</code></td><td>array</td><td><strong>yes</strong></td><td>Rule groups; must yield at least one valid path</td></tr></tbody></table><p>A missing <code>name</code>, or no valid path anywhere in <code>groups</code>, gets the source rejected on add.</p><h2 id="group-fields" tabindex="-1">Group fields <a class="header-anchor" href="#group-fields" aria-label="Permalink to &quot;Group fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>no</td><td>Group name. Empty shows as &quot;Ungrouped&quot;</td></tr><tr><td><code>enabled</code></td><td>bool</td><td>no</td><td><strong>Defaults to <code>true</code></strong>. Set <code>false</code> to ship the group off by default; users can turn it on</td></tr><tr><td><code>paths</code></td><td>array</td><td><strong>yes</strong></td><td>Cleaning paths in this group</td></tr></tbody></table><p>Groups are an organizational device — cleaning flattens them. Still, group carefully: users browse and toggle rules per group, so a source that dumps hundreds of paths into one group is painful to use.</p><h2 id="writing-paths" tabindex="-1">Writing paths <a class="header-anchor" href="#writing-paths" aria-label="Permalink to &quot;Writing paths&quot;">​</a></h2><p>Paths <strong>must be absolute</strong>. Glob patterns are supported:</p><table tabindex="0"><thead><tr><th>Pattern</th><th>Meaning</th></tr></thead><tbody><tr><td><code>*</code></td><td>Any characters within one segment</td></tr><tr><td><code>?</code></td><td>A single character</td></tr><tr><td><code>[abc]</code></td><td>One character from the set</td></tr><tr><td><code>**</code></td><td>Recursive match across directory levels</td></tr></tbody></table><p>Common roots:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/storage/emulated/0/Android/data/&lt;package&gt;/   App external private dir</span></span>
<span class="line"><span>/data/data/&lt;package&gt;/                         App internal data dir</span></span>
<span class="line"><span>/data/user/0/&lt;package&gt;/                       Same, multi-user form</span></span>
<span class="line"><span>/data/media/0/                                Equivalent to /storage/emulated/0</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Directories are cleaned recursively</p><p>A directory path means <strong>every file under it</strong> gets cleaned, then the empty directories are removed. Target real cache dirs like <code>cache</code> or <code>log</code> — never a parent like <code>files</code> that may hold user data.</p></div><h2 id="paths-that-get-rejected" tabindex="-1">Paths that get rejected <a class="header-anchor" href="#paths-that-get-rejected" aria-label="Permalink to &quot;Paths that get rejected&quot;">​</a></h2><p>Every path is validated on fetch. Offending entries are <strong>dropped individually</strong>; the source itself still loads:</p><ul><li>Relative paths not starting with <code>/</code></li><li>Anything containing <code>..</code> (prevents escaping the intended target)</li><li>Longer than 512 chars, or shorter than 2</li></ul><h2 id="size-limits" tabindex="-1">Size limits <a class="header-anchor" href="#size-limits" aria-label="Permalink to &quot;Size limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th><th>On exceeding</th></tr></thead><tbody><tr><td>File size</td><td>2 MB</td><td>Whole source rejected</td></tr><tr><td>Path count</td><td>5000</td><td>Extras dropped; the first 5000 still apply</td></tr></tbody></table><h2 id="hosting" tabindex="-1">Hosting <a class="header-anchor" href="#hosting" aria-label="Permalink to &quot;Hosting&quot;">​</a></h2><h3 id="recommended-your-own-repo" tabindex="-1">Recommended: your own repo <a class="header-anchor" href="#recommended-your-own-repo" aria-label="Permalink to &quot;Recommended: your own repo&quot;">​</a></h3><p>Any HTTPS endpoint returning JSON works. The easiest route is a GitHub repo of your own:</p><ol><li>Create a public repo, e.g. <code>your-name/czero-rules</code></li><li>Put the rule file in it, e.g. <code>rules.json</code></li><li>Distribute the raw link:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://raw.githubusercontent.com/&lt;user&gt;/&lt;repo&gt;/main/rules.json</span></span></code></pre></div><p>The response must be bare JSON. Note that a GitHub <strong>web</strong> URL (<code>github.com/.../blob/...</code>) returns an HTML page, not JSON — users pasting it will get &quot;The file is not valid JSON&quot;.</p><div class="warning custom-block"><p class="custom-block-title">http/https only</p><p>Schemes like <code>file://</code> and <code>content://</code> are rejected.</p></div><p>Self-hosting keeps you in full control: what changes and when is up to you. Keeping rules in Git also means you can roll back a bad change and answer user issues against a diff. Bump <code>version</code> in the JSON when you publish — users see it change in the app.</p><div class="tip custom-block"><p class="custom-block-title">Request volume is not a concern</p><p><code>raw.githubusercontent.com</code> rate-limits <strong>per visitor IP</strong>, not per repository, so it doesn&#39;t matter how many people subscribe to yours. And each user fetches each source once a day.</p></div><h3 id="fallback-the-czero-repo" tabindex="-1">Fallback: the CZero repo <a class="header-anchor" href="#fallback-the-czero-repo" aria-label="Permalink to &quot;Fallback: the CZero repo&quot;">​</a></h3><p>If maintaining a repo really isn&#39;t practical for you, open an <a href="https://github.com/Xocio/CZero/issues" target="_blank" rel="noreferrer">issue</a> asking to place your JSON under <code>rules/public/</code> in the CZero repo:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://raw.githubusercontent.com/Xocio/CZero/main/rules/public/&lt;filename&gt;.json</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Storage only</p><p>CZero does <strong>not</strong> review rule content. Being hosted here implies no vetting and no endorsement — correctness and safety remain the author&#39;s responsibility. This exists for people who can&#39;t host their own; if you can, do.</p></div><h2 id="subscribing" tabindex="-1">Subscribing <a class="header-anchor" href="#subscribing" aria-label="Permalink to &quot;Subscribing&quot;">​</a></h2><p>CZeroX → Settings → Custom rules → <code>⋯</code> (top right) → Add rule source → paste the link.</p><p>A new card appears titled with your <code>name</code> and subtitled with <code>author</code>, showing group count, rule count and last update time. Tapping it opens the full rule list.</p><h2 id="update-behavior" tabindex="-1">Update behavior <a class="header-anchor" href="#update-behavior" aria-label="Permalink to &quot;Update behavior&quot;">​</a></h2><ul><li>When a user opens the rule sources page and more than <strong>24 hours</strong> have passed since the last sync, every enabled source is fetched automatically</li><li>Users can also tap the refresh icon on a card</li><li>An update <strong>replaces the source&#39;s rules wholesale</strong> — your file wins</li><li>Re-adding the same URL counts as an update; it will not create a second card</li></ul><div class="warning custom-block"><p class="custom-block-title">Local edits are overwritten</p><p>Users can add, edit and delete your rules locally (say, to disable a group temporarily), but those edits are wiped on the next update — ownership is decided by the <code>source</code> key in the JSON, and updates only trust the source file. This is by design; changes users want to keep belong in their built-in rules.</p></div><h2 id="execution" tabindex="-1">Execution <a class="header-anchor" href="#execution" aria-label="Permalink to &quot;Execution&quot;">​</a></h2><p>Your rules are handed to <code>list/customize</code> alongside the built-in ones and behave identically:</p><ul><li><strong>Recycle bin</strong>: matched files are moved to <code>/storage/emulated/0/Recycle</code>, not deleted outright. Users can restore them, kept 7 days by default</li><li><strong>Temporal barrier</strong>: if enabled, only files older than N days are cleaned</li><li><strong>Whitelist</strong>: the user&#39;s <code>clean_whitelist.json</code> wins; whitelisted paths are skipped</li><li><strong>Nested dedup</strong>: if a parent directory is already listed, paths under it are ignored automatically</li></ul><p>So duplicates are harmless — writing too broadly is not.</p><h2 id="recommendations" tabindex="-1">Recommendations <a class="header-anchor" href="#recommendations" aria-label="Permalink to &quot;Recommendations&quot;">​</a></h2><ol><li><strong>Verify on your own device first.</strong> Load the rules as built-in rules in CZeroX, run a cycle, confirm both the reclaimed size and the app&#39;s behavior before publishing.</li><li><strong>Only clean regenerable data.</strong> Caches, logs, crash dumps and temp downloads are safe; chat history, drafts, download folders and credentials are not.</li><li><strong>One group per app</strong>, named after the app, so users can toggle what they care about.</li><li><strong>Bump <code>version</code> on every change.</strong> Users can&#39;t see a diff, but they can see the version move.</li><li><strong>Use <code>**</code> sparingly.</strong> Recursive matching is slow on large trees and easy to over-match.</li><li><strong>Ship risky groups disabled.</strong> Set <code>&quot;enabled&quot;: false</code> when unsure and let the user opt in.</li></ol>`,49)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
